import{_ as s,a0 as r,w as o,s as p,ao as u,I as l,x as e,a1 as i,A as n}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const c=JSON.parse('{"title":"用 Skanlite 在 Linux 上掃描文件和老照片 | LCTT x X-CMD","titleTemplate":false,"description":"用 Skanlite 在 Linux 上掃描文件和老照片 | LCTT (202203) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"用 Skanlite 在 Linux 上掃描文件和老照片 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"用 Skanlite 在 Linux 上掃描文件和老照片 | LCTT (202203) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202203/20220224 Scan documents and old photos on Linux with Skanlite","title":"用 Skanlite 在 Linux 上掃描文件和老照片","tag":"202203","desc":""},"relativePath":"202203/20220224 Scan documents and old photos on Linux with Skanlite.md","filePath":"[post].md"}'),d={name:"202203/20220224 Scan documents and old photos on Linux with Skanlite.md"};function k(h,t,b,m,S,x){const a=r("Link");return o(),p("div",null,[t[15]||(t[15]=u('<h1 id="用-skanlite-在-linux-上掃描文件和老照片" tabindex="-1">用 Skanlite 在 Linux 上掃描文件和老照片 <a class="header-anchor" href="#用-skanlite-在-linux-上掃描文件和老照片" aria-label="Permalink to “用 Skanlite 在 Linux 上掃描文件和老照片”">​</a></h1><blockquote><p>使用這個 Linux KDE 應用，將你的檔案數字化。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/202203/27/114937eannabb3zn45lraa.jpg" alt=""></p><p>雖然現在的世界已經大部分實現了數字化，但仍有一些時候，你還是需要打印一份表格，簽字，然後把它掃描回來。有時候，我發現在手機上拍個快照就夠了，但有些行業需要比草率的快照更好的複印件，因此平板掃描儀是必要的。KDE 項目提供了一個叫做 Skanlite 的應用程序，它可以幫助你導入在平板上掃描的文件，甚至是用聯機相機掃描的文件。</p><h3 id="在-linux-上安裝-skanlite" tabindex="-1">在 Linux 上安裝 Skanlite <a class="header-anchor" href="#在-linux-上安裝-skanlite" aria-label="Permalink to “在 Linux 上安裝 Skanlite”">​</a></h3><p>你可以從你的軟件庫中安裝 Skanlite。在 Fedora、Mageia 和類似的地方：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf install skanlite</span></span></code></pre></div><p>在 Elementary、Linux Mint 和其他基於 Debian 的發行版上：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt install skanlite</span></span></code></pre></div><h3 id="掃描儀驅動" tabindex="-1">掃描儀驅動 <a class="header-anchor" href="#掃描儀驅動" aria-label="Permalink to “掃描儀驅動”">​</a></h3><p>市場上的大多數掃描儀都與 SANE 掃描儀 API 兼容。SANE 並不是一個真正的驅動，而是一個協議，可以接收來自圖像採集設備的輸入，併為希望圍繞它建立一個應用的程序員提供選項。Skanlite 就是這樣一個應用。</p><p>我還沒有遇到過不與 SANE 接口兼容的掃描儀，但可能也有不與 SANE 接口兼容的掃描儀。在這些情況下，請在製造商的網站上尋找 SANE 或 TWAIN 的驅動，或者尋找它們專有的驅動和掃描儀接口。後者可能無法使用 Skanlite，但當你不確定你的掃描儀是否通過標準協議進行通信時，Skanlite 總是值得試試。我甚至遇到過打印機和掃描儀的二合一設備，儘管打印機需要一個額外的驅動，但掃描儀卻能立即被識別。</p><h3 id="使用-skanlite" tabindex="-1">使用 Skanlite <a class="header-anchor" href="#使用-skanlite" aria-label="Permalink to “使用 Skanlite”">​</a></h3><p>當你啓動 Skanlite 時，它首先會在你的系統中搜索圖像採集設備。在筆記本電腦上，Skanlite 通常會發現網絡攝像頭是一個有效的輸入源（因為它是），但它也會找到連接到你機器上的平板掃描儀。選擇你要使用的掃描儀，然後繼續。</p><p>要看掃描的內容，點擊應用程序右下角的“<ruby>預覽<rt>Preview</rt></ruby>”按鈕。</p><p><img src="https://opensource.com/sites/default/files/skanlite.png" alt="Skanlite with custom artwork" title="Skanlite with custom artwork"></p><p>這將在右面板上顯示一個預覽圖像。沒有任何東西被保存到你的硬盤上，這只是顯示你的掃描儀上目前有什麼。</p><h3 id="選擇一個掃描區域" tabindex="-1">選擇一個掃描區域 <a class="header-anchor" href="#選擇一個掃描區域" aria-label="Permalink to “選擇一個掃描區域”">​</a></h3><p>如果你只需要掃描儀上的一部分內容，你可以選擇一個你想保存的區域。要選擇一個單一的區域，在你想保存的區域上點擊並拖動你的鼠標。當有一個有效的選擇時，當你點擊“<ruby>掃描<rt>Scan</rt></ruby>”按鈕時，只有你選擇的那部分會被保存。</p><p>你可以有一個以上的選區，當你需要掃描幾個小圖像或只掃描一個大文件的特定部分時，這特別有效。要添加一個選區，請點擊出現在選區中心的 “+” 圖標。</p><p><img src="https://opensource.com/sites/default/files/skanlite-selection.jpg" alt="Adding selections" title="Adding selections"></p><p>你可以通過點擊 “-” 圖標來刪除選區，當你有多個活動選區時，該圖標會出現。</p><h3 id="掃描設置" tabindex="-1">掃描設置 <a class="header-anchor" href="#掃描設置" aria-label="Permalink to “掃描設置”">​</a></h3><p>圖像採集設置位於左邊的面板上。這些控件允許你導入彩色或灰度的圖像，並對圖像的亮度和對比度進行調整。這些選項是基於軟件的，不影響你的掃描儀的行為方式，但它們是常見的調整，在這裏做這些調整可以使你不必在 GIM 或 Gwenview 中對圖像進行後期處理。</p><p>在許多情況下，你的掃描儀可能有可配置的設置，可在 Skanlite 窗口左側的“<ruby>掃描儀特定選項<rt>Scanner Specific Options</rt></ruby>”標籤中找到。有些掃描儀允許你調整色温、亮度、飽和度和其他出現在固件中的屬性。可用的選項根據設備和供應商的不同而不同，所以你有可能在這個面板上看到變化，這取決於你與哪種設備的對接。</p><h3 id="掃描和保存" tabindex="-1">掃描和保存 <a class="header-anchor" href="#掃描和保存" aria-label="Permalink to “掃描和保存”">​</a></h3><p>當你準備好導入圖像（或圖像的選定區域，如果你已經做了選擇）時，點擊 Skanlite 窗口右下角的“<ruby>掃描<rt>Scan</rt></ruby>”按鈕。根據你的設備，它可能需要一些時間來創建掃描，但當它完成後，會提示你保存或丟棄圖像。如果你喜歡你所看到的，點擊“<ruby>保存<rt>Save</rt></ruby>”。</p><p>圖像會被保存到你所配置的任何默認位置。要查看默認位置，點擊窗口右下角的“<ruby>設置<rt>Settings</rt></ruby>”按鈕。在 “<ruby>Skanlite 設置<rt>Skanlite Settings</rt></ruby>”中，你可以設置默認保存位置、默認名稱格式和圖像分辨率。你還可以控制每次掃描後是否提示你保存或丟棄圖像，或者你是否想要保存所有的東西並在以後進行分類。</p><h3 id="linux-上的掃描很容易" tabindex="-1">Linux 上的掃描很容易 <a class="header-anchor" href="#linux-上的掃描很容易" aria-label="Permalink to “Linux 上的掃描很容易”">​</a></h3><p>在 Linux 上掃描文件是如此簡單，我很少考慮這個問題。通常不需要你去尋找和安裝特殊的驅動或應用，因為像 Skanlite 這樣的應用使用開放協議，使這個過程變得簡單。下次你有一份需要數字化的拷貝時，用 Skanlite 導入它。</p><hr>',31)),l("p",null,[t[1]||(t[1]=e("via: ",-1)),i(a,{href:"https://opensource.com/article/22/2/scan-documents-skanlite-linux-kde"},{default:n(()=>[...t[0]||(t[0]=[e("https://opensource.com/article/22/2/scan-documents-skanlite-linux-kde",-1)])]),_:1})]),l("p",null,[t[6]||(t[6]=e("作者：",-1)),i(a,{href:"https://opensource.com/users/seth"},{default:n(()=>[...t[2]||(t[2]=[e("Seth Kenlon",-1)])]),_:1}),t[7]||(t[7]=e(" 選題：",-1)),i(a,{href:"https://github.com/lujun9972"},{default:n(()=>[...t[3]||(t[3]=[e("lujun9972",-1)])]),_:1}),t[8]||(t[8]=e(" 譯者：",-1)),i(a,{href:"https://github.com/geekpi"},{default:n(()=>[...t[4]||(t[4]=[e("geekpi",-1)])]),_:1}),t[9]||(t[9]=e(" 校對：",-1)),i(a,{href:"https://github.com/wxy"},{default:n(()=>[...t[5]||(t[5]=[e("wxy",-1)])]),_:1})]),l("p",null,[t[12]||(t[12]=e("本文由 ",-1)),i(a,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...t[10]||(t[10]=[e("LCTT",-1)])]),_:1}),t[13]||(t[13]=e(" 原創編譯，",-1)),i(a,{href:"https://linux.cn/"},{default:n(()=>[...t[11]||(t[11]=[e("Linux中國",-1)])]),_:1}),t[14]||(t[14]=e(" 榮譽推出",-1))])])}const L=s(d,[["render",k]]);export{c as __pageData,L as default};
